mapper.select:
SELECT BASE_DATE, BRANCH_CODE, EMP_NO,
       START_AMT, REAL_AMT, CLOSE_YN
  FROM TB_CASH
 WHERE BASE_DATE   = #{baseDate}
   AND BRANCH_CODE = #{branchCode}
   AND EMP_NO      = #{empNo}

SELECT NVL(SUM(CASE WHEN AMOUNT > 0 THEN AMOUNT ELSE 0 END), 0) AS IN_AMT,
       NVL(SUM(CASE WHEN AMOUNT < 0 THEN -AMOUNT ELSE 0 END), 0) AS OUT_AMT
  FROM TB_TR_HIST
 WHERE TR_DATE     = #{baseDate}
   AND BRANCH_CODE = #{branchCode}
   AND EMP_NO      = #{empNo}
   AND RES_CODE    = '0000'

mapper.update:
UPDATE TB_CASH
   SET REAL_AMT  = #{realAmt},
       CLOSE_YN  = 'Y',
       CLOSE_DTM = CURRENT_TIMESTAMP
 WHERE BASE_DATE   = #{baseDate}
   AND BRANCH_CODE = #{branchCode}
   AND EMP_NO      = #{empNo}

UPDATE TB_BIZ_DATE
   SET CLOSE_YN = 'Y'
 WHERE BASE_DATE = #{baseDate}
